package com.sanctuarygames.createtransit;
import com.sanctuarygames.createtransit.elevator.*;import com.sanctuarygames.createtransit.elevator.model.*;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.neoforged.neoforge.gametest.*;import net.neoforged.neoforge.common.util.FakePlayerFactory;import net.minecraft.world.entity.decoration.ArmorStand;import java.util.*;
@GameTestHolder("createtransit") @PrefixGameTestTemplate(false)
public final class UpdateCabinGameTests {
 private static void check(boolean b,String m){if(!b)throw new GameTestAssertException(m);}
 @GameTest(template="elevator2_shaft",batch="update_cabin",timeoutTicks=180) public static void standard_entrance_updates_in_place(GameTestHelper h){upgrade(h,false);}
 @GameTest(template="elevator2_shaft",batch="update_cabin",timeoutTicks=180) public static void wide_entrance_updates_in_place(GameTestHelper h){upgrade(h,true);}
 private static void upgrade(GameTestHelper h,boolean wide){var list=new ArrayList<ElevatorDriveEntity>();var l=h.getLevel();var player=FakePlayerFactory.getMinecraft(l);player.getAbilities().mayBuild=true;player.setPos(h.absolutePos(new BlockPos(26,2,22)).getCenter());int index=0;
  for(var direction:Direction.Plane.HORIZONTAL){var pos=h.absolutePos(new BlockPos(5+index%2*10,2,5+index/2*10));index++;l.setBlock(pos,ElevatorRegistry.DRIVE.get().defaultBlockState().setValue(ElevatorPartBlock.FACING,direction),3);var d=(ElevatorDriveEntity)l.getBlockEntity(pos);d.onLoad();for(int y=1;y<=13;y++)l.setBlock(pos.above(y),(y==1||y==13?ElevatorRegistry.FLOOR_MARKER_RAIL:ElevatorRegistry.GUIDE_RAIL).get().defaultBlockState().setValue(ElevatorPartBlock.FACING,direction),3);d.rescan();d.configureModel("size","3");d.configureModel("kit3",Boolean.toString(wide));d.configureModel("primary","1");d.configureModel("secondary","5");d.configureModel("lighting","RING");d.configureModel("chime","SCHINDLER_HT");check(d.configureModel("revertCabin","true"),"Start from V13 geometry: "+d.model().warning());for(var f:d.floorList())check(d.installModelLanding(player,f.y()),"Landing prepared");check(d.activateModel(),"Old model cabin active: "+d.model().warning());check(!d.configureModel("updateCabin","true"),"Pending initial trip blocks conversion");list.add(d);}
  h.runAfterDelay(100,()->{for(var d:list){var model=d.model();var cabin=model.entity();var identity=cabin.getUUID();var location=cabin.position();var controllerId=d.identifier();var floors=d.floorList();var before=model.config().save();var motion=model.state();
   var rider=new ArmorStand(l,cabin.world(1.5,.125,1.5).x,cabin.getY()+.125,cabin.world(1.5,.125,1.5).z);l.addFreshEntity(rider);check(!d.configureModel("updateCabin","true"),"Occupied update refused");check(model.config().legacyGeometry(),"Rejected update leaves configuration intact");rider.discard();
   check(d.configureModel("updateCabin","true"),"Update accepted: "+model.warning());check(cabin==model.entity()&&identity.equals(cabin.getUUID())&&location.equals(cabin.position()),"Same entity and position retained");check(controllerId.equals(d.identifier())&&floors.equals(d.floorList()),"Controller and discovered floor identities retained");before.setProperty("legacyGeometry","false");check(CabinConfiguration.load(before).equals(model.config()),"Every existing appearance setting preserved");check(Math.abs(cabin.getBoundingBox().getYsize()-2.8)<1e-8,"Height upgraded to the V17 2.8: "+cabin.getBoundingBox().getYsize());check(motion.equals(model.state()),"Motion state unchanged");for(var floor:floors){var base=model.landingPosition(floor.y(),false);check(l.getBlockEntity(base) instanceof ModelLandingEntity door&&d.getBlockPos().equals(door.markerDrive()),"Landing link preserved");}var saved=model.save();var restored=new ModelCabinController(d);restored.load(saved);check(!restored.config().legacyGeometry(),"Upgrade persists across reload");check(d.configureModel("updateCabin","true"),"Repeated update harmless");check(d.model().request(floors.getLast().y()),"Updated cabin still accepts a destination");}h.succeed();});
 }
}
